def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: dict[str, bool] = {}
    history: list[tuple] = []
    rejected: list[int] = []

    def amount(tok):
        # Only plain decimal digits, no sign; leading zeros allowed.
        if tok and all("0" <= c <= "9" for c in tok):
            return int(tok)
        return None

    for idx, op in enumerate(ops):
        parts = op.split(" ")
        verb, nargs = parts[0], len(parts)
        record = None
        ok = False

        if verb == "undo" and nargs == 1:
            # Undo is never recorded, so it cannot be reverted.
            if history:
                ok = True
                entry = history.pop()
                if entry[0] == "open":
                    del balances[entry[1]]
                    del frozen[entry[1]]
                elif entry[0] == "bal":
                    for name, delta in entry[1]:
                        balances[name] += delta
                elif entry[0] == "frozen":
                    frozen[entry[1]] = entry[2]

        elif verb == "open" and nargs == 3:
            name, amt = parts[1], amount(parts[2])
            if amt is not None and name not in balances:
                balances[name] = amt
                frozen[name] = False
                record = ("open", name)
                ok = True

        elif verb == "deposit" and nargs == 3:
            name, amt = parts[1], amount(parts[2])
            if amt is not None and amt > 0 and name in balances:
                balances[name] += amt
                record = ("bal", ((name, -amt),))
                ok = True

        elif verb == "withdraw" and nargs == 3:
            name, amt = parts[1], amount(parts[2])
            if (amt is not None and amt > 0 and name in balances
                    and not frozen[name] and balances[name] >= amt):
                balances[name] -= amt
                record = ("bal", ((name, amt),))
                ok = True

        elif verb == "transfer" and nargs == 4:
            src, dst, amt = parts[1], parts[2], amount(parts[3])
            if (amt is not None and amt > 0 and src != dst
                    and src in balances and dst in balances
                    and not frozen[src] and balances[src] >= amt):
                balances[src] -= amt
                balances[dst] += amt
                record = ("bal", ((src, amt), (dst, -amt)))
                ok = True

        elif verb == "freeze" and nargs == 2:
            name = parts[1]
            if name in balances and not frozen[name]:
                frozen[name] = True
                record = ("frozen", name, False)
                ok = True

        elif verb == "unfreeze" and nargs == 2:
            name = parts[1]
            if name in balances and frozen[name]:
                frozen[name] = False
                record = ("frozen", name, True)
                ok = True

        if not ok:
            rejected.append(idx)
        elif record is not None:
            history.append(record)

    return balances, rejected
